16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.CityLocality;
20	import org.springframework.samples.petclinic.util.CustomerCode;
21	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
22	
23	import jakarta.persistence.*;
