30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "membership_number")
76	    private String membershipNumber;
77	
78	    @Column(name = "bulk_signup_warning", nullable = false)
79	    private boolean bulkSignupWarning;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    /**
117	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
118	     * against the city's region and then stored verbatim. Optional, so may be null.
119	     */
120	    public String getPostcode() {
121	        return this.postcode;
122	    }
123	
124	    public void setPostcode(String postcode) {
125	        this.postcode = postcode;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getCustomerCode() {
137	        return this.customerCode;
138	    }
139	
140	    public void setCustomerCode(String customerCode) {
141	        this.customerCode = customerCode;
142	    }
143	
144	    public String getHouseholdId() {
145	        return this.householdId;
146	    }
147	
148	    public void setHouseholdId(String householdId) {
149	        this.householdId = householdId;
150	    }
151	
152	    public Integer getNamesakeCount() {
153	        return this.namesakeCount;
154	    }
155	
156	    public void setNamesakeCount(Integer namesakeCount) {
157	        this.namesakeCount = namesakeCount;
158	    }
159	
160	    public Integer getHouseholdSize() {
161	        return this.householdSize;
162	    }
163	
164	    public void setHouseholdSize(Integer householdSize) {
165	        this.householdSize = householdSize;
166	    }
167	
168	    public String getMembershipNumber() {
169	        return this.membershipNumber;
170	    }
171	
172	    public void setMembershipNumber(String membershipNumber) {
173	        this.membershipNumber = membershipNumber;
174	    }
175	
176	    /**
177	     * Whether this owner was created as part of a bulk signup: {@code true} when more
178	     * than 80 owners had already been registered on this owner's registration date at
179	     * the moment it was created, {@code false} otherwise. Captured at creation.
180	     */
181	    public boolean isBulkSignupWarning() {
182	        return this.bulkSignupWarning;
183	    }
184	
185	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
186	        this.bulkSignupWarning = bulkSignupWarning;
187	    }
188	
189	    /**
190	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
191	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
192	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
193	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
194	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
195	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
196	     * region is derived directly from the stored postcode and city. Derived from stored
197	     * state, never persisted.
198	     */
199	    public String getLocality() {
200	        String region = CustomerCode.regionOf(this.customerCode);
201	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
202	    }
203	
204	    /**
205	     * The owner's membership level, from 1 to 3: starts at 1, gains 1 when this owner has
206	     * an email address, and gains 1 when this owner had no namesakes at creation
207	     * ({@code namesakeCount} is 0). Capped at 3 (level 4 is reserved for tenure). Derived
208	     * from stored state, never persisted.
209	     */
210	    public int getMembershipLevel() {
211	        int level = 1;
212	        if (hasEmail()) {
213	            level++;
214	        }
215	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
216	            level++;
217	        }
218	        return Math.min(level, 3);
219	    }
220	
221	    /**
222	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
223	     * the {@code customerCode}. Derived from stored state, never persisted.
224	     */
225	    public int getCheckDigit() {
226	        return LuhnCheckDigit.of(this.customerCode);
227	    }
228	
229	    /**
230	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
231	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
232	     */
233	    public String getContactPreference() {
234	        return hasEmail() ? "EMAIL" : "PHONE";
235	    }
236	
237	    /**
238	     * The owner's identity key: the single value all duplicate detection is expressed
239	     * through, formed as the normalized telephone, the email (or empty when absent) and
240	     * the household id (or empty when none), joined by {@code '|'}. Two owners are
241	     * duplicates only when their whole identity keys are equal, so members of the same
242	     * household with different telephones have different keys and are all allowed. Derived
243	     * from stored state, never persisted.
244	     */
245	    public String getIdentityKey() {
246	        String emailPart = hasEmail() ? this.email : "";
247	        String householdPart = this.householdId == null ? "" : this.householdId;
248	        return this.telephone + "|" + emailPart + "|" + householdPart;
249	    }
250	
251	    private boolean hasEmail() {
252	        return this.email != null && !this.email.isEmpty();
253	    }
254	
255	    protected Set<Pet> getPetsInternal() {
256	        if (this.pets == null) {
257	            this.pets = new HashSet<>();
258	        }
259	        return this.pets;
260	    }
261	
262	    protected void setPetsInternal(Set<Pet> pets) {
263	        this.pets = pets;
264	    }
265	
266	    public List<Pet> getPets() {
267	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
268	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
269	        return Collections.unmodifiableList(sortedPets);
270	    }
271	
272	    public void setPets(List<Pet> pets) {
273	        this.pets = new HashSet<>(pets);
274	    }
275	
276	    public void addPet(Pet pet) {
277	        getPetsInternal().add(pet);
278	        pet.setOwner(this);
279	    }
280	
281	    /**
282	     * Return the Pet with the given name, or null if none found for this Owner.
283	     *
284	     * @param name to test
285	     * @return true if pet name is already in use
286	     */
287	    public Pet getPet(String name) {
288	        return getPet(name, false);
289	    }
290	
291	    /**
292	     * Return the Pet with the given name, or null if none found for this Owner.
293	     *
294	     * @param name to test
295	     * @return true if pet name is already in use
296	     */
297	    public Pet getPet(String name, boolean ignoreNew) {
298	        name = name.toLowerCase();
299	        for (Pet pet : getPetsInternal()) {
300	            if (!ignoreNew || !pet.isNew()) {
301	                String compName = pet.getName();
302	                compName = compName.toLowerCase();
303	                if (compName.equals(name)) {
304	                    return pet;
305	                }
306	            }
307	        }
308	        return null;
309	    }
310	
311	    public Pet getPet(Integer petId) {
312	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
313	    }
314	
315	    @Override
316	    public String toString() {
317	        return new ToStringCreator(this)
318	
319	            .append("id", this.getId())
320	            .append("new", this.isNew())
321	            .append("lastName", this.getLastName())
322	            .append("firstName", this.getFirstName())
323	            .append("address", this.address)
324	            .append("city", this.city)
325	            .append("telephone", this.telephone)
326	            .toString();
327	    }
328	}
