5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Validates an owner request's optional registration date: an absent date is left for
11	 * {@link DefaultOwnerRegistrationDate} to stamp. A supplied date later than the server's
12	 * current date is rejected with a 400. Nothing is mutated.
13	 */
14	public class ValidateOwnerRegistrationDate {
15	
16	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
17	        LocalDate registrationDate = request.getRegistrationDate();
18	        if (registrationDate == null) {
19	            return;
20	        }
21	        LocalDate serverDate = LocalDate.now();
22	        if (registrationDate.isAfter(serverDate)) {
23	            throw new FutureRegistrationDateException(registrationDate, serverDate);
24	        }
25	    }
26	}
