5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Defaults the create-owner registration date: when the request omits it, stamps the
10	 * server's current date so every new owner has one. A supplied date is left untouched.
11	 * Mutates the shared request in place so {@link BuildOwner} persists the value.
12	 */
13	public class DefaultOwnerRegistrationDate {
14	
15	    public void service(@Val OwnerFieldsDto request) {
16	        if (request.getRegistrationDate() == null) {
17	            request.setRegistrationDate(LocalDate.now());
18	        }
19	    }
20	}
