1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
5	 * characters are ignored, so the algorithm applies unchanged to formatted values such as
6	 * an owner's customer code ({@code NSW-1A2B3C4D}).
7	 *
8	 * <p>Walking right to left, every second digit (starting with the rightmost) is doubled,
9	 * casting out nines, and the check digit is the amount needed to bring the running total
10	 * to a multiple of ten.
11	 */
12	public final class LuhnCheckDigit {
13	
14	    private LuhnCheckDigit() {
15	    }
